package com.csust.eyediagnosis.workflow.explanation;
import com.csust.eyediagnosis.workflow.domain.*; import com.csust.eyediagnosis.workflow.evidence.*; import com.csust.eyediagnosis.workflow.risk.*; import org.junit.jupiter.api.Test; import java.util.Set; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class ExplanationActionsTest {
 @Test void policyActionsArePureAndDraftIsGated(){ DeterministicClinicalRiskPolicy p=new DeterministicClinicalRiskPolicy(); ClinicalRiskPrecheckAction pre=new ClinicalRiskPrecheckAction(p); assertEquals(PublicationRiskDisposition.LIMITED_SAFETY_ABSTENTION,pre.execute(new ClinicalRiskPrecheckInput(InferenceOutcomeType.SAFETY_ABSTENTION,PredictionExposureStatus.WITHHELD_BY_ABSTENTION,ImageQualityDecision.PASS,"fp")).disposition()); ClinicalRiskFinalAction fin=new ClinicalRiskFinalAction(p); EvidenceSufficiency e=new EvidenceSufficiency(0,Set.of(),Set.of(),false,EvidenceSufficiencyReasonCode.REWRITE_EXHAUSTED); assertEquals(PublicationRiskDisposition.LIMITED_EVIDENCE,fin.execute(new ClinicalRiskFinalInput(InferenceOutcomeType.VALID_PREDICTION,PredictionExposureStatus.AVAILABLE,ImageQualityDecision.PASS,e,true,false)).disposition()); }
}
